 private static function descriptor(int $fd,int $size,bool $output=false):mixed{Guard::require($fd>=3&&$fd<=64,'DESCRIPTOR_NUMBER');$h=@fopen('php://fd/'.$fd,'rb');Guard::require(is_resource($h),'DESCRIPTOR');$s=fstat($h);Guard::require($s!==false&&($s['mode']&0170000)===0100000&&($s['mode']&0777)===0600&&$s['uid']===posix_geteuid()&&$s['nlink']===1&&$s['size']<=$size&&(!$output||$s['size']===0),'DESCRIPTOR_PERMISSIONS');if($output){$out=@fopen('php://fd/'.$fd,'wb');Guard::require(is_resource($out),'OUTPUT_DESCRIPTOR');$v=fstat($out);Guard::require($v!==false&&$v['dev']===$s['dev']&&$v['ino']===$s['ino']&&$v['size']===0,'OUTPUT_IDENTITY');fclose($h);return $out;}return $h;}
 public static function main(array $arguments):int{$key=null;try{Guard::gate();$command=array_shift($arguments);Guard::require(in_array($command,['init','seal','backup','restore','verify','cleanup','status','keygen'],true),'COMMAND');$o=[];foreach($arguments as $arg){Guard::require(preg_match('/\A--(config-fd|key-fd|key-out-fd|operation-id)=([a-zA-Z0-9]+)\z/D',$arg,$m)===1&&!isset($o[$m[1]]),'ARGUMENTS');$o[$m[1]]=$m[2];}if($command==='keygen'){Guard::fields($o,['key-out-fd']);Guard::require(ctype_digit($o['key-out-fd']),'DESCRIPTOR');$out=self::descriptor((int)$o['key-out-fd'],0,true);try{$key=random_bytes(SODIUM_CRYPTO_SECRETSTREAM_XCHACHA20POLY1305_KEYBYTES);Guard::write($out,$key);Guard::require(fflush($out)&&fsync($out),'KEY_SYNC');}finally{fclose($out);}$result=['status'=>'PRIVATE_KEY_GENERATED','key_bits'=>256,'key_in_stdout'=>false];}else{Guard::fields($o,$command==='init'?['config-fd','key-fd']:['config-fd','key-fd','operation-id']);Guard::require(ctype_digit($o['config-fd'])&&ctype_digit($o['key-fd'])&&$o['config-fd']!==$o['key-fd'],'DESCRIPTOR');$cf=self::descriptor((int)$o['config-fd'],4096);$kf=self::descriptor((int)$o['key-fd'],32);try{$raw=stream_get_contents($cf,4097);$key=stream_get_contents($kf,33);Guard::require(is_string($raw)&&strlen($raw)<=4096&&is_string($key)&&strlen($key)===32,'PRIVATE_INPUT_SIZE');$config=json_decode($raw,true,8,JSON_THROW_ON_ERROR);Guard::require(is_array($config),'CONFIG');}finally{fclose($cf);fclose($kf);}$w=$command==='init'?Workspace::create($config):Workspace::load($o['operation-id'],$config);$result=match($command){'init'=>['status'=>'NEW_SYNTHETIC_NATIVE_SOURCE','operation_id'=>$w->id],'seal'=>$w->seal(),'backup'=>Rehearsal::backup($w,$key),'restore'=>Rehearsal::restore($w,$key),'verify'=>Rehearsal::verify($w,$key),'cleanup'=>$w->cleanup(),'status'=>['status'=>'LOCAL_STATE_ONLY_NOT_ARCHIVE_ATTESTATION','operation_id'=>$w->id,'source'=>$w->state()['source_state'],'backup'=>$w->state()['backup'],'target'=>$w->state()[